package com.example.saasguide.communication.application.web;
import com.example.saasguide.communication.application.error.ApplicationNotFoundException; import com.example.saasguide.communication.application.error.ContextInvalidException; import com.example.saasguide.communication.application.error.EligibilityDeniedException; import com.example.saasguide.communication.application.error.EligibilityServiceUnavailableException; import com.example.saasguide.communication.application.context.RequestContextFilter; import com.example.saasguide.communication.application.context.ServiceRequestContext; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice; import org.springframework.web.client.RestClientResponseException;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ContextInvalidException.class) ResponseEntity<ApiError> context(ContextInvalidException e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"CONTEXT_INVALID","요청 컨텍스트가 올바르지 않습니다.",r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"REQUEST_INVALID","요청 내용이 올바르지 않습니다.",r);} @ExceptionHandler(EligibilityDeniedException.class) ResponseEntity<ApiError> denied(EligibilityDeniedException e,HttpServletRequest r){return error(HttpStatus.UNPROCESSABLE_ENTITY,"ELIGIBILITY_DENIED","자격 요건을 충족하지 않습니다.",r);} @ExceptionHandler({EligibilityServiceUnavailableException.class,RestClientResponseException.class}) ResponseEntity<ApiError> unavailable(Exception e,HttpServletRequest r){return error(HttpStatus.SERVICE_UNAVAILABLE,"ELIGIBILITY_SERVICE_UNAVAILABLE","자격 검증 서비스를 일시적으로 사용할 수 없습니다.",r);} @ExceptionHandler(ApplicationNotFoundException.class) ResponseEntity<ApiError> missing(Exception e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"APPLICATION_NOT_FOUND","신청을 찾을 수 없습니다.",r);} private ResponseEntity<ApiError> error(HttpStatus s,String c,String m,HttpServletRequest r){return ResponseEntity.status(s).body(new ApiError(c,m,contextValue(r, true),contextValue(r, false),Instant.now()));} private String contextValue(HttpServletRequest r, boolean requestId){Object value=r.getAttribute(RequestContextFilter.ATTRIBUTE); if(value instanceof ServiceRequestContext c)return requestId?c.requestId():c.traceId(); return r.getHeader(requestId?"X-Request-Id":"X-Trace-Id");} public record ApiError(String code,String message,String requestId,String traceId,Instant timestamp){} }
